/*
 * A239147  Numbers n such that there exists a k>0 such that all six of n +/-
 *          k, n^2 +/- k, and n^3 +/- k are prime.
 * https://oeis.org/A239147
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   Return the n-th integer n for which there exists a k>0 such that
 *            n±k, n²±k and n³±k are all prime. The sequence is generated by
 *            testing successive n and caching the ones that satisfy the
 *            condition
 * Range:     u8 none, u16 n <= 3, u32 n <= 4, u64 n <= 50, u128 n <= 50,
 *            big any n
 * Helpers:   is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Includes */
#include <stdbool.h>
#include <stdint.h>
#include <stddef.h>
#include <stdlib.h>
#include "../utils/is_prime_big.h"

/* Function */
seq_t a(idx_t n)
{
    /* index n starts at 1 */
    static idx_t scanned_n = 1;                 /* next n to test */
    static size_t cache_size = 0;               /* number of terms found */
    static size_t cache_cap = 0;                /* capacity of cache */
    static seq_t *cache = NULL;                 /* memoized terms */

    /* Grow cache when needed */
    if (n > cache_size) {
        while (cache_size < n) {
            uint64_t cur = scanned_n;          /* current n to test (fits 64-bit) */
            bool found = false;
            /* Pre-compute squares and cubes in seq_t */
            seq_t nsq  = (seq_t)cur * (seq_t)cur;
            seq_t ncu  = nsq * (seq_t)cur;

            for (uint64_t k = 1; k < cur; ++k) {
                seq_t a1 = (seq_t)(cur - k);
                seq_t a2 = (seq_t)(cur + k);
                seq_t a3 = nsq - (seq_t)k;
                seq_t a4 = nsq + (seq_t)k;
                seq_t a5 = ncu - (seq_t)k;
                seq_t a6 = ncu + (seq_t)k;

                if (!is_prime_big(a1) || !is_prime_big(a2) ||
                    !is_prime_big(a3) || !is_prime_big(a4) ||
                    !is_prime_big(a5) || !is_prime_big(a6))
                    continue;

                found = true;
                break;
            }

            if (found) {
                if (cache_size == cache_cap) {
                    cache_cap = (cache_cap ? 2 * cache_cap : 16);
                    cache = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
                }
                cache[cache_size++] = (seq_t)cur;
            }

            ++scanned_n;
        }
    }

    return cache[n - 1];
}
